<template>
  <main class="nw-workspace">
    <header><router-link to="/fundthred/noteworthy"><NoteworthyBrand /></router-link><div class="nw-inline-actions"><select v-if="practices.length" aria-label="Your payroll practice" :value="practice?.agencyId || ''" @change="switchPractice($event.target.value)"><option v-for="p in practices" :key="p.agencyId" :value="p.agencyId">{{ p.name }}</option></select><button @click="signOut">Sign out</button></div></header>
    <div class="nw-workspace-body">
      <p v-if="loading" role="status">Opening your payroll workspace…</p><p v-if="error" class="nw-alert nw-alert-error" role="alert">{{ error }}</p><p v-if="message" class="nw-alert" role="status">{{ message }}</p>
      <template v-if="!loading && !practice"><section class="nw-panel"><h1>Your NoteWorthy workspace</h1><p>Create your practice to begin setting up payroll. Employees can open the invitation sent by their practice.</p><router-link to="/fundthred/noteworthy/start">Create a practice →</router-link><button v-if="error" @click="loadWorkspace">Try again</button></section></template>
      <template v-if="!loading && practice">
        <div class="nw-workspace-title"><div><p class="eyebrow">{{ isOwner ? 'Practice payroll' : 'Your payroll portal' }}</p><h1>{{ practice.name }}</h1><p>{{ isOwner ? 'From billing reports to clear, reviewable pay. Keep the payroll processor you already use.' : 'Your posted payroll statements, with a clear view of what you earned.' }}</p></div><span class="nw-badge" :class="{'nw-badge-pending':isOwner && !activation?.canImport}">{{ isOwner ? activation?.canImport ? 'Data access active' : 'Setup in progress' : 'Employee access' }}</span></div>
        <nav v-if="isOwner" class="nw-workspace-nav" aria-label="Payroll workspace"><button v-for="tab in tabs" :key="tab.id" :aria-current="activeTab===tab.id?'page':undefined" @click="goTab(tab.id)">{{ tab.label }}</button></nav>
        <template v-if="!isOwner"><section class="nw-panel"><h2>Your posted statements</h2><p>These amounts are prepared service pay and adjustments. Your payroll processor issues the final payslip and payment.</p><div v-if="!paystubs.length" class="nw-empty">No posted payroll statements yet. Your practice will publish them here after reviewing payroll.</div><label v-else>Pay period<select v-model="selectedStatement"><option v-for="stub in paystubs" :key="stub.id" :value="stub.id">{{ date(stub.periodStart) }} → {{ date(stub.periodEnd) }}</option></select></label><template v-if="statement"><p class="nw-small">Posted {{ date(statement.postedAt) }}</p><div class="nw-statement-total">{{ money(statement.totalAmount) }}</div><div class="nw-table-scroll"><table class="nw-table"><thead><tr><th>Service date</th><th>Service code</th><th>Units / hours</th><th>Rate</th><th>Pay</th></tr></thead><tbody><tr v-for="(line,i) in statementLines" :key="i"><td>{{ line.serviceDate ? date(line.serviceDate) : 'Period total' }}</td><td>{{ line.serviceCode }}</td><td>{{ line.units }}</td><td>{{ line.rateAmount===null || line.rateAmount===undefined ? '—' : money(line.rateAmount) }}</td><td>{{ money(line.amount) }}</td></tr></tbody></table></div><p>Service pay: {{ money(statement.subtotalAmount) }} · Adjustments: {{ money(statement.adjustmentsAmount) }}</p></template></section></template>
        <template v-else-if="activeTab==='payroll' && activation?.canImport"><PayrollWizardView :key="practice.agencyId" :workspace-base="base" :wizard-base="`${base}/payroll`" /></template>
        <template v-else-if="activeTab==='agreements'"><OrganizationAgreementsView :key="practice.agencyId" embedded :initial-agency-id="practice.agencyId" /></template>
        <template v-else-if="activeTab==='team'"><section class="nw-panel"><h2>Your team & compensation</h2><p>Your billing report creates practice-specific employee records. Confirm credentials, emails, and pay per service code here. Invite each person when their details are ready.</p><div v-if="!employees.length" class="nw-empty">Your roster will appear after your first billing-report import. Set credential defaults below before you begin.</div><div v-else class="nw-table-scroll"><table class="nw-table"><thead><tr><th>Employee</th><th>Credential</th><th>Email</th><th>Pay setup</th><th>Portal</th><th></th></tr></thead><tbody><tr v-for="employee in employees" :key="employee.userId"><td>{{ employee.firstName }} {{ employee.lastName }}</td><td>{{ employee.credential || 'Confirm credential' }}</td><td>{{ employee.email || 'Add email' }}</td><td><span class="nw-badge" :class="{'nw-badge-pending':employee.missingServiceCodes?.length}">{{ employee.missingServiceCodes?.length ? `${employee.missingServiceCodes.length} rates needed` : 'Review rates' }}</span></td><td>{{ employee.portalActive ? 'Active' : employee.invitedAt ? 'Invited' : 'Not invited' }}</td><td><button @click="editEmployee(employee)">Edit & review</button></td></tr></tbody></table></div>
          <form v-if="editing" class="nw-rate-editor" @submit.prevent="saveEmployee"><h3>{{ editing.firstName }} {{ editing.lastName }}</h3><div class="nw-form-pair"><label>Credential<input v-model="employeeForm.credential" maxlength="80" placeholder="e.g. LPC" /></label><label>Employee email<input v-model="employeeForm.email" type="email" maxlength="254" /></label></div><p class="nw-small">The most recent saved rate for each service code is shown. Change its effective date to start a new rate; saved payroll history is protected.</p><p class="nw-small">Use the effective date for these rates. Existing dated pay history is retained; pro bono services always pay $0.</p><RateRows v-model="employeeForm.rates" /><div class="nw-inline-actions"><button type="button" @click="employeeForm.rates.push(newRate())">Add service code</button><button :disabled="busy">Save employee & rates</button><button type="button" @click="editing=null">Close</button><button type="button" :disabled="busy || !editing.email || editing.portalActive" @click="inviteEmployee">{{ editing.portalActive ? 'Portal active' : 'Send portal invitation' }}</button></div><p class="nw-small">Save a verified email address first. Sending an invitation grants this person access to their own posted statements.</p></form>
        </section><section class="nw-panel"><h2>Credential defaults</h2><p>Create a starting rate table for each credential. Defaults fill missing rates when you assign a credential; an employee’s explicit rate is retained.</p><div v-for="(group,index) in defaults" :key="index" class="nw-rate-editor"><label>Credential<input v-model="group.credential" maxlength="80" placeholder="e.g. LCSW" /></label><RateRows v-model="group.rates" /><div class="nw-inline-actions"><button @click="group.rates.push(newRate())">Add service code</button><button @click="defaults.splice(index,1)">Remove credential</button></div></div><div class="nw-inline-actions"><button @click="defaults.push({credential:'',rates:[newRate()]})">Add credential defaults</button><button :disabled="busy" @click="saveDefaults">Save defaults</button></div></section></template>
        <template v-else-if="activeTab==='runs'"><section class="nw-panel"><h2>Pay periods</h2><p>Create the period covered by your TherapyNotes report. The wizard brings current work and prior-period changes together.</p><form class="nw-period-form" @submit.prevent="createPeriod"><label>Period start<input v-model="periodForm.periodStart" required type="date" /></label><label>Period end<input v-model="periodForm.periodEnd" required type="date" :min="periodForm.periodStart" /></label><button class="nw-submit" :disabled="busy">Create pay period</button></form><div v-if="!periods.length" class="nw-empty">Create your first pay period to get started.</div><div v-else class="nw-table-scroll"><table class="nw-table"><thead><tr><th>Period</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="period in periods" :key="period.id"><td>{{ date(period.period_start) }} → {{ date(period.period_end) }}</td><td><span class="nw-badge">{{ period.status }}</span></td><td><router-link v-if="activation?.canImport" :to="`${base}/payroll/${period.id}`">{{ period.status==='posted' ? 'View payroll' : 'Open payroll wizard' }} →</router-link><span v-else class="nw-small">Complete secure data activation to upload</span></td></tr></tbody></table></div></section></template>
        <template v-else><div class="nw-setup-grid"><section class="nw-panel"><p class="eyebrow">A clear path to payroll</p><h2>{{ activation?.canImport ? 'Your practice is ready for reports.' : 'Set up your practice.' }}</h2><ol class="nw-requirements"><li><strong>Practice account created.</strong> Your workspace and records belong to your practice.</li><li><strong>Confirm your agreements.</strong> Complete your payroll service agreement, order, and BAA with FundThred.</li><li><strong>Configure compensation.</strong> Add credential defaults now, then confirm employee rates after the report creates your roster.</li><li><strong>Upload and review.</strong> Follow the wizard, post statements, and export to your current payroll processor.</li></ol><router-link :to="`${base}/agreements`">Open practice agreements →</router-link><button class="nw-submit" @click="goTab(activation?.canImport?'runs':'team')">{{ activation?.canImport ? 'Start a payroll →' : 'Set up compensation defaults →' }}</button></section><section class="nw-panel"><p class="eyebrow">Powered by Auricwell</p><h2>Secure data activation</h2><p v-if="activation?.canImport">Your practice’s agreement and data-access review is complete. You can upload billing reports through the payroll wizard.</p><template v-else><p>Account setup and compensation tables are available now. FundThred reviews the executed agreements and practice readiness before enabling real billing-report uploads.</p><ul><li v-for="requirement in activation?.requirements || []" :key="requirement.id">{{ requirement.label }}</li></ul><p v-if="activation?.requestedAt" class="nw-alert">Activation review requested. Your existing request is saved.</p><form v-else @submit.prevent="requestActivation"><label>Practice legal name<input v-model="activationForm.legalName" required maxlength="200" autocomplete="organization" /></label><label>Practice legal address<textarea v-model="activationForm.legalAddress" required maxlength="1000" autocomplete="street-address" /></label><button :disabled="busy">Request activation review</button></form><button :disabled="busy" @click="run(() => loadPractice())">Refresh activation status</button></template><p class="nw-small">Need to see the workflow while setup is in progress?</p><router-link to="/fundthred/noteworthy/demo">Try the complete fictional demo →</router-link></section></div></template>
      </template>
    </div>
  </main>
</template>
<script setup>
import { computed, defineAsyncComponent, defineComponent, h, onMounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useAgencyStore } from '../store/agency';
import { useAuthStore } from '../store/auth';
import api from '../services/api';
import NoteworthyBrand from '../components/noteworthy/NoteworthyBrand.vue';
import { money } from '../content/noteworthyPayroll';
import '../styles/noteworthyPayroll.css';
import '../styles/noteworthyWorkspace.css';
import { useFundThredBranding } from '../composables/useFundThredBranding';
useFundThredBranding('Your Payroll | NoteWorthy by FundThred');
const PayrollWizardView=defineAsyncComponent(()=>import('./admin/PayrollWizardView.vue'));
const OrganizationAgreementsView=defineAsyncComponent(()=>import('./admin/OrganizationAgreementsView.vue'));
const route=useRoute(),router=useRouter(),agencyStore=useAgencyStore(),auth=useAuthStore();
const practices=ref([]),practice=ref(null),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),activation=ref(null),employees=ref([]),periods=ref([]),defaults=ref([]),paystubs=ref([]),selectedStatement=ref(null),editing=ref(null);
const activationForm=reactive({legalName:'',legalAddress:''});
const employeeForm=reactive({email:'',credential:'',rates:[]}),periodForm=reactive({periodStart:'',periodEnd:'',payDate:''});
const isOwner=computed(()=>practice.value?.role==='owner'),base=computed(()=>`/fundthred/noteworthy/app/${practice.value?.agencyId}`);
const tabs=[{id:'setup',label:'Overview & setup'},{id:'runs',label:'Pay periods'},{id:'team',label:'Team & rates'},{id:'agreements',label:'Practice agreements'}];
const activeTab=computed(()=>route.name==='NoteworthyPayroll'?'payroll':route.name==='NoteworthyAgreements'?'agreements':['team','runs'].includes(route.query.tab)?route.query.tab:'setup');
const statement=computed(()=>paystubs.value.find(p=>p.id===selectedStatement.value));
const statementLines=computed(()=>statement.value?.lines?.flatMap(line=>line.datedRateLines?.length?line.datedRateLines.map(dated=>({...dated,serviceCode:line.serviceCode})):[line]) || []);
const config={headers:{'X-Noteworthy-Request':'1'},skipGlobalLoading:true};
let generation=0;
const date=value=>String(value || '').slice(0,10);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const newRate=()=>({serviceCode:'',rateAmount:'',rateUnit:'per_unit',effectiveStart:periodForm.periodStart || today()});
const RateRows=defineComponent({props:{modelValue:{type:Array,required:true}},emits:['update:modelValue'],setup(props,{emit}){return()=>h('div',{class:'nw-table-scroll'},[h('table',{class:'nw-table'},[h('thead',[h('tr',['Service code','Rate ($)','Basis','Effective date',''].map(label=>h('th',label)))]),h('tbody',props.modelValue.map((rate,index)=>h('tr',{key:index},[h('td',[h('input',{value:rate.serviceCode,required:true,maxlength:32,'aria-label':`Service code ${index+1}`,onInput:e=>rate.serviceCode=e.target.value})]),h('td',[h('input',{value:rate.rateAmount,type:'number',min:0,max:100000,step:.01,required:true,'aria-label':`Rate ${index+1}`,onInput:e=>rate.rateAmount=e.target.value})]),h('td',[h('select',{value:rate.rateUnit,'aria-label':`Rate basis ${index+1}`,onChange:e=>rate.rateUnit=e.target.value},[h('option',{value:'per_unit'},'Per unit'),h('option',{value:'per_hour'},'Per hour')])]),h('td',[h('input',{value:rate.effectiveStart,type:'date',required:true,'aria-label':`Effective date ${index+1}`,onInput:e=>rate.effectiveStart=e.target.value})]),h('td',[h('button',{type:'button','aria-label':`Remove rate ${index+1}`,onClick:()=>emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index))},'Remove')])])) )])]);}});
function endpoint(suffix=''){return `/noteworthy/practices/${practice.value.agencyId}${suffix}`;}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e.response?.data?.error?.message || 'We could not complete that request. Please try again.';}finally{busy.value=false;}}
async function loadWorkspace(){loading.value=true;error.value='';const current=++generation;try{const {data}=await api.get('/noteworthy/workspace',{skipGlobalLoading:true});if(current!==generation)return;practices.value=data.practices || [];const requested=Number(route.params.agencyId);const next=requested?practices.value.find(p=>p.agencyId===requested):practices.value[0];practice.value=next || null;if(requested && !next)throw new Error('This practice is not available to your account.');if(!next)return;if(!requested){await router.replace(`/fundthred/noteworthy/app/${next.agencyId}`);return;}agencyStore.setCurrentAgency({id:next.agencyId,name:next.name,slug:next.slug,organization_type:'agency',has_payroll_access:next.role==='owner'});await loadPractice(current);}catch(e){if(current===generation)error.value=e.response?.data?.error?.message || e.message || 'Your workspace could not be loaded.';}finally{if(current===generation)loading.value=false;}}
async function loadPractice(current=generation){if(!practice.value)return;const id=practice.value.agencyId;editing.value=null;if(isOwner.value){const results=await Promise.all([api.get(`/noteworthy/practices/${id}/activation`,{skipGlobalLoading:true}),api.get(`/noteworthy/practices/${id}/roster`,{skipGlobalLoading:true}),api.get(`/noteworthy/practices/${id}/rate-defaults`,{skipGlobalLoading:true}),api.get('/payroll/periods',{params:{agencyId:id},skipGlobalLoading:true})]);if(current!==generation || practice.value?.agencyId!==id)return;activation.value=results[0].data;activationForm.legalName=activation.value.legalIdentity?.legalName || '';activationForm.legalAddress=activation.value.legalIdentity?.legalAddress || '';employees.value=results[1].data.employees || [];defaults.value=results[2].data.defaults || [];periods.value=Array.isArray(results[3].data)?results[3].data:results[3].data.periods || [];}else{const {data}=await api.get(`/noteworthy/practices/${id}/me/paystubs`,{skipGlobalLoading:true});if(current!==generation || practice.value?.agencyId!==id)return;paystubs.value=data.paystubs || [];selectedStatement.value=paystubs.value[0]?.id;}}
async function goTab(tab){error.value='';message.value='';await router.push(tab==='agreements'?`${base.value}/agreements`:{path:base.value,query:tab==='setup'?{}:{tab}});await run(()=>loadPractice());}
function switchPractice(id){return router.push(`/fundthred/noteworthy/app/${id}`);}
async function signOut(){await auth.logout();await router.push('/fundthred/noteworthy');}
function editEmployee(employee){editing.value=employee;employeeForm.email=employee.email || '';employeeForm.credential=employee.credential || '';const latestRates=[...new Map((employee.rates || []).map(rate=>[rate.serviceCode,rate]).reverse()).values()];employeeForm.rates=latestRates.map(rate=>({serviceCode:rate.serviceCode,rateAmount:rate.rateAmount,rateUnit:rate.rateUnit,effectiveStart:date(rate.effectiveStart)})).concat((employee.missingServiceCodes || []).map(code=>({...newRate(),serviceCode:typeof code==='string'?code:code.serviceCode})));if(!employeeForm.rates.length && !employee.rates?.length)employeeForm.rates=[newRate()];message.value='';error.value='';}
function saveEmployee(){return run(async()=>{const selectedId=editing.value.userId;await api.patch(endpoint(`/roster/${selectedId}`),{email:employeeForm.email || null,credential:employeeForm.credential || null,...(employeeForm.rates.length?{rates:employeeForm.rates}: {})},config);await loadPractice();message.value='Employee details and dated rates saved. Existing pay history is retained.';});}
function inviteEmployee(){return run(async()=>{const {data}=await api.post(endpoint(`/roster/${editing.value.userId}/invite`),{confirm:true},config);await loadPractice();message.value=data.invitationSent?'Portal invitation sent.':data.deliveryPending?'Invitation queued; delivery is pending.':'Invitation saved; email delivery is not confirmed. Please retry.';});}
function saveDefaults(){return run(async()=>{await api.put(endpoint('/rate-defaults'),{defaults:defaults.value},config);message.value='Credential defaults saved.';});}
function requestActivation(){return run(async()=>{activation.value=(await api.post(endpoint('/activation-request'),{...activationForm},config)).data;message.value='Your activation review request is saved.';});}
function createPeriod(){return run(async()=>{const {data}=await api.post(endpoint('/periods'),{periodStart:periodForm.periodStart,periodEnd:periodForm.periodEnd,...(periodForm.payDate?{payDate:periodForm.payDate}:{})},config);await loadPractice();message.value='Pay period created.';if(activation.value?.canImport)await router.push(`${base.value}/payroll/${data.id}`);});}
watch(()=>route.params.agencyId,(id,old)=>{if(id!==old)loadWorkspace();});
onMounted(loadWorkspace);
</script>
